        // Let's do that:
        uint256 huge = type(uint256).max - 1;
        vm.deal(caller, type(uint256).max);
        vm.prank(caller);
        c.Put{value: huge}(block.timestamp);

        // Now second deposit
        vm.prank(caller);
        // In reference, this reverts because huge + 2 overflows; in bug, it passes
        // We need to catch this: for reference, we expect revert; for bug, we expect success.
        // Since the test must pass on reference and fail on bug, we need the assertion to be true for reference.
        // So we assert that after both deposits, calling Collect fails in reference but succeeds in bug.
