pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up a specific caller
        address alice = address(0x123);
        vm.deal(alice, 2 ether);

        // Deposit exactly 1 ether with unlockTime = block.timestamp + 1
        vm.prank(alice);
        c.Put{value: 1 ether}(block.timestamp + 1);

        // Warp past unlockTime
        vm.warp(block.timestamp + 2);

        // Try Collect(1 ether) — reference succeeds, buggy reverts
        bool success;
        vm.prank(alice);
        try c.Collect(1 ether) {
            success = true;
        } catch {
            success = false;
        }

        // Reference: success = true (balance check passes with overflow guard)
        // Buggy: success = false (balance wraps, require(revert) or underflow)
        // Using getter to confirm: reference has balance 0, buggy has max uint
        uint256 balanceAfter = c.Acc(alice).balance;
        assertTrue(success == true && balanceAfter == 0);
    }
}

