pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: give user address 1 ether, then call Put with exactly MinSum
        vm.deal(address(0x1234), 1 ether);
        vm.prank(address(0x1234));
        c.Put{value: 1 ether}(block.timestamp + 100);

        // Warp past unlock time
        vm.warp(block.timestamp + 200);

        // Now try to Collect exactly 1 ether from address 0x1234
        vm.prank(address(0x1234));
        bool ok;
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference, balance was increased to 1 ether, so Collect succeeds (ok == true)
        // In the buggy version, balance is never increased (stays 0), so Collect reverts (ok == false)
        assertTrue(ok);
    }
}

