pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fundamental difference: Put adds msg.value to balance in reference, but not in buggy.
        // To exploit: first user puts 1 ether (MinSum), second user puts 1 ether (to test revert vs success).
        address user1 = address(0x1234);
        address user2 = address(0x5678);

        vm.deal(user1, 1 ether);
        vm.prank(user1);
        c.Put{value: 1 ether}(0);  // In reference, user1.balance becomes 1 ether; in buggy, remains 0.

        vm.deal(user2, 1 ether);
        vm.prank(user2);
        c.Put{value: 1 ether}(0);  // user2.balance becomes 1 ether in reference; 0 in buggy.

        // To make Collect call from user1 test the divergence:
        // In reference, user1 has 1 ether balance (>= MinSum), so Collect(1 ether) succeeds and balance goes to 0.
        // In buggy, user1 has 0 balance, so Collect(1 ether) reverts (balance < MinSum or balance < _am).
        vm.warp(block.timestamp + 1000); // ensure unlockTime passed

        bool ok;
        vm.prank(user1);
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }

        assertTrue(ok); // reference passes (ok = true), buggy fails (ok = false)
    }
}

