pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x123);
        address bob = address(0x456);

        // Alice puts 1 ether via Put
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Put{value: 1 ether}(block.timestamp + 1000);

        // Bob sends 1 ether via fallback (calls Put(0)), but Alice's balance never changes
        vm.deal(bob, 1 ether);
        vm.prank(bob);
        (bool success,) = address(c).call{value: 1 ether}("");
        require(success, "fallback failed");

        // Alice tries to collect 1 ether (MinSum == 1 ether)
        vm.warp(block.timestamp + 1001);
        bool ok;
        vm.prank(alice);
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

