contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: user sends 2 ether with unlockTime far in the future
        address user = address(0x1234);
        uint256 futureUnlock = block.timestamp + 1000;
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.Put{value: 2 ether}(futureUnlock);

        // Warp to exactly the future unlock time
        vm.warp(futureUnlock);

        // Now user tries to collect 1 ether
        vm.prank(user);
        bool ok;
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference C: requires block.timestamp > acc.unlockTime (strictly greater).
        // Since block.timestamp == futureUnlock == acc.unlockTime, the condition fails -> Collect reverts -> ok == false.
        // Buggy M: sets unlockTime = block.timestamp during Put, so acc.unlockTime == futureUnlock as well.
        // But during Collect, block.timestamp == futureUnlock, so condition block.timestamp > acc.unlockTime is false too.
        // Wait — that means both revert? Let me re-evaluate.
        // Actually, the difference is: reference sets unlockTime = max(block.timestamp_at_Put, _unlockTime) = futureUnlock (since futureUnlock > block.timestamp_at_Put).
        // Bug sets unlockTime = block.timestamp_at_Put = block.timestamp before warp. After warp to futureUnlock, bug's unlockTime is old block.timestamp (e.g., 0), so block.timestamp > old timestamp is true, so Collect succeeds.
        // Reference: unlockTime == futureUnlock, so block.timestamp == futureUnlock, not >, so Collect reverts.
        assertTrue(!ok, "Reference should revert, buggy allows");
    }
}

