contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: give caller 2 ether, warp to allow collection
        address caller = address(0x1234);
        vm.deal(caller, 2 ether);
        vm.warp(1000);

        // Put 1 ether to create balance >= MinSum (1 ether)
        vm.prank(caller);
