        // So we can get the Log address and call History(0) on it.
        address logAddr = c.LogFile();
        bool ok;
        try Log(logAddr).History(0) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract Log {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

