contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract so it has balance to collect
        vm.deal(address(c), 10 ether);
        // First, fund the caller (this contract) via Put
        vm.prank(address(this));
        c.Put{value: 2 ether}(0);
        // Warp past unlockTime (Put set unlockTime to block.timestamp, which is 0, so any later time works)
        vm.warp(1);
        // Now call Collect with amount 1 ether (which is >= MinSum=1 ether)
        vm.prank(address(this));
        c.Collect(1 ether);
        // Check the Log contract's History length via the public getter
        // The getter for Log is public, so we can access it via c.LogFile() then call History.length?
        // Actually LogFile is a public variable, so c.LogFile() returns the Log contract address.
        // Then we can call History.length on that contract. But we need to cast to Log type.
        // Simpler: deploy a separate Log contract and use it as the logFile? No, we must use the existing one.
        // The Log contract is deployed inside C constructor. We can get its address via c.LogFile().
        address logAddr = c.LogFile();
        // Create a reference to Log interface to call History length
        // We'll use a low-level call to History(uint256) to check if index 0 exists
        // Alternatively, we can try a direct call: (bool success, bytes memory data) = logAddr.call(abi.encodeWithSignature("History(uint256)", 0));
        // If revert on buggy (length 0), success false; on reference (length 1), success true.
        (bool success,) = logAddr.call(abi.encodeWithSignature("History(uint256)", 0));
