pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Put{value: 1 ether}(block.timestamp);
        vm.warp(block.timestamp + 1 days);
        // Now acc.balance = 1 ether, MinSum = 1 ether, acc.unlockTime = block.timestamp (the previous block.timestamp)
        // We warp to exactly that unlockTime so block.timestamp == acc.unlockTime
        // Use the stored unlockTime from the previous Put call, which is the old block.timestamp
        // Actually we need to get the exact unlockTime. Since Put set unlockTime = max(_unlockTime, block.timestamp)
        // with _unlockTime = block.timestamp, so unlockTime = block.timestamp (the time of Put).
        // After vm.warp(block.timestamp + 1 days), current time is > unlockTime.
        // To make block.timestamp == unlockTime, we read it.
        uint unlockTime = c.Acc(alice).unlockTime;
        vm.warp(unlockTime);

        vm.prank(alice);
        bool ok;
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: if condition false (strict > required, but == given), so no revert, ok = true
        // Mutant: require fails (strict > required, == not sufficient), so revert, ok = false
        assertTrue(ok);
    }
}
